import React from 'react';

// Component that decides whether to render an image or not based on its URL
const ImageWithFallback = ({ imageUrl, altText }) => {
  const notAvailableImages = [
    "http://i.annihil.us/u/prod/marvel/i/mg/b/40/image_not_available.jpg",
    "https://i.annihil.us/u/prod/marvel/i/mg/f/60/4c002e0305708.gif",
  ];

  // Check if the image URL is in the list of "not available" images
  const isImageAvailable = !notAvailableImages.includes(imageUrl);

  return (
    <>
      {isImageAvailable && <img src={imageUrl} alt={altText} />}
    </>
  );
};

export default ImageWithFallback;
